INSERT OR IGNORE INTO settings(id,data) VALUES(1,'{"hero_title":"Little steps.\nLifelong confidence.","hero_intro":"Discover the joy of Irish dance with Clare and Lisa Watson. A welcoming dance community in Templeogue, South Dublin, with room for every dancer to grow.","announcement":"Your dance journey starts here — explore our classes","email":"dance@watsontwinacademy.ie","phone_clare":"087 9011243","phone_lisa":"087 9731425","address":"Spawell Complex, Templeogue, Dublin, D6W PY06","about":"Identical twins Clare and Lisa have been dancing since the age of four. Qualified with An Chomhdháil in 2013, they bring a shared love of Irish dance, years of performance experience and a personal approach to every class.\n\nTheir purpose-built studios at the Spawell Complex are a home for learning, friendship and the joy of movement.","privacy":"Watson Twin Academy uses the information you provide to respond to your enquiry and help you find a suitable class. Please provide a parent or guardian’s contact details and avoid including sensitive information about a child.\n\nEnquiries are stored in our website database and sent to the academy’s designated inbox. Cloudflare provides website hosting and storage; Resend processes enquiry notification emails. Only authorised academy administrators can access enquiries.\n\nTo ask about your information, request a correction or request deletion, contact dance@watsontwinacademy.ie.","reply_time":"Clare or Lisa will get back to you to discuss a suitable class."}');
INSERT OR IGNORE INTO courses(id,slug,title,category,summary,description,image,published,sort_order) VALUES('irish-dance','irish-dance','Irish Dance','Irish dance','Find your rhythm, build confidence and become part of our Irish dance family.','Explore the rhythm, movement and tradition of Irish dance with Clare and Lisa. Contact us to discuss the right class for your child’s age and experience.','/assets/irish-dance.jpg',1,0);
INSERT OR IGNORE INTO courses(id,slug,title,category,summary,description,image,published,sort_order) VALUES('lyrical','lyrical','Lyrical & Contemporary','Performing arts','A little imagination. A lot of expression. Discover a new way to move.','Explore expressive movement through lyrical and contemporary dance at WTA Dance Studios. Ask us about current classes and suitable experience levels.','/assets/lyrical.jpg',1,1);
INSERT OR IGNORE INTO courses(id,slug,title,category,summary,description,image,published,sort_order) VALUES('acro','acro-gymnastics','Acro & Gymnastics','Performing arts','Develop coordination and explore movement, one new skill at a time.','Acro and gymnastics are part of the wider WTA Dance Studios programme. Contact the team for current age groups, class availability and what to bring.','/assets/acro.jpg',1,2);
INSERT OR IGNORE INTO courses(id,slug,title,category,summary,description,image,published,sort_order) VALUES('jazz','jazz-hiphop','Jazz & Hiphop','Performing arts','Bring your energy and discover the fun of dancing to a different beat.','Our wider performing arts programme includes modern jazz and hiphop / commercial dance. Ask the team about current classes.','/assets/lyrical.jpg',1,3);
INSERT OR IGNORE INTO courses(id,slug,title,category,summary,description,image,published,sort_order) VALUES('theatre','musical-theatre','Musical Theatre & Singing','Performing arts','Make room for your voice, your imagination and your love of the stage.','Discover musical theatre and vocal training through WTA Dance Studios. Contact us for details of the current programme.','/assets/studio.jpg',1,4);
INSERT OR IGNORE INTO courses(id,slug,title,category,summary,description,image,published,sort_order) VALUES('competition','competition','Competition & Teams','Irish dance','Take the next step in your dance journey with the academy.','For dancers interested in competition classes and team opportunities, Clare and Lisa can advise on experience requirements and the next suitable step.','/assets/irish-dance.jpg',1,5);
